 const nav:{id:Page;icon:LucideIcon;ar:string;en:string}[]=[...(canEdit?[{id:"community" as Page,icon:Bell,ar:"رسائل وإعلانات الأعضاء",en:"Member messages & posts"}]:[]),...(canEdit?[{id:"competitions" as Page,icon:Dumbbell,ar:"البطولات والإنجازات",en:"Competitions & achievements"}]:[]),...(canEdit?[{id:"hr" as Page,icon:Users,ar:"الموظفون والرواتب",en:"Staff & payroll"}]:[]),...(canEdit?[{id:"book" as Page,icon:Wallet,ar:"الخزنة والمصروفات والموردون",en:"Cash desk & suppliers"}]:[]),...(canEdit?[{id:"engagement" as Page,icon:Bell,ar:"المتابعة والتكاملات والدعم",en:"Follow-up & support"}]:[]),...(canEdit?[{id:"coaches" as Page,icon:Dumbbell,ar:"المدربون الخارجيون",en:"External coaches"},{id:"shifts" as Page,icon:Clock,ar:"شيفتات الأعضاء",en:"Member shifts"},{id:"whatsapp" as Page,icon:Bell,ar:"واتساب النادي",en:"Club WhatsApp"}]:[]),...(admin?[{id:"import" as Page,icon:Download,ar:"استيراد ونسخ احتياطي",en:"Import & backups"}]:[]),{id:"music",icon:Music2,ar:"موسيقى النادي",en:"Music room"},{id:"users",icon:Users,ar:"المستخدمون والصلاحيات",en:"Users & permissions"},{id:"announcements",icon:Bell,ar:"الرسائل الصوتية",en:"Voice announcements"},{id:"shop",icon:Wallet,ar:"متجر المكملات",en:"Supplement store"},{id:"training",icon:Dumbbell,ar:"برامج التدريب",en:"Training programs"},{id:"operations",icon:ShieldCheck,ar:"تشغيل النادي",en:"Club operations"},{id:"overview",icon:LayoutDashboard,ar:"نظرة عامة",en:"Overview"},{id:"members",icon:Users,ar:"الأعضاء",en:"Members"},{id:"cards",icon:ShieldCheck,ar:"كروت الحضور",en:"Member passes"},{id:"attendance",icon:CheckCircle2,ar:"الحضور",en:"Attendance"},{id:"classes",icon:CalendarDays,ar:"الحصص والحجوزات",en:"Classes & bookings"},{id:"pulse",icon:Zap,ar:"Gym Pulse",en:"Gym Pulse"},{id:"finance",icon:Wallet,ar:"التحصيل",en:"Collections"},{id:"reports",icon:BarChart3,ar:"التقارير",en:"Reports"},{id:"activity",icon:Activity,ar:"سجل النشاط",en:"Activity"},{id:"settings",icon:Settings,ar:"الإعدادات",en:"Settings"} ];const navOrder:Page[]=["overview","operations","members","attendance","cards","book","finance","classes","training","coaches","competitions","shifts","shop","pulse","reports","engagement","community","whatsapp","announcements","music","hr","users","import","activity","settings"];nav.sort((a,b)=>navOrder.indexOf(a.id)-navOrder.indexOf(b.id));
