  <div className="hero"><div className="hero-copy"><span className="hero-kicker"><i/>{t("ناديك، على إيقاع أفضل","YOUR CLUB. IN PERFECT RHYTHM.")}</span><h2>{t("كل حركة.","Every move.")}<br/><em>{t("تصنع فرقًا.","Makes a difference.")}</em></h2><p>{t("الأرقام تحكي قصة ناديك. وإنت تختار خطوته الجاية.","Your numbers tell a story. You decide what comes next.")}</p><button className="hero-button" onClick={()=>go("reports")}>{t("استكشف أداء النادي","Explore club performance")}{arrow}</button></div><div className="hero-orbits" aria-hidden="true"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="orbit orbit-three"/><div className="hero-core"><Dumbbell size={46} strokeWidth={1.4}/></div><span className="orbit-dot one"/><span className="orbit-dot two"/><span className="floating-note"><Activity size={16}/>{t("حركة مستمرة","Always in motion")}</span></div><div className="hero-score"><span>{t("الاشتراكات النشطة","Active memberships")}</span><strong>{percentage}<small>%</small></strong><span>{active.length} / {members.length} {t("عضو","members")}</span><div className="score-track"><i style={{width:percentage+"%"}}/></div></div></div>
