function SettingsPanel({state,admin,ar,busy,branch,onBranch,onModal,demo,onLanguage,onExport,mutate}:{state:GymState;admin:boolean;ar:boolean;busy:boolean;branch:string;onBranch:(id:string)=>void;onModal:(modal:Modal)=>void;demo:boolean;onLanguage:()=>void;onExport:(kind:"members"|"payments")=>void;mutate:(operation:Omit<Operation,"branch">&{type:string})=>Promise<boolean>}){const s=state,canEdit=admin,t=(a:string,b:string)=>ar?a:b,selectedTheme=themes.find(theme=>theme.id===state.settings.theme)??themes[0];return <fieldset className="workspace-permissions" disabled={!admin}><DesktopTools ar={ar} role={admin?"owner":"reception"}/>{SectionHead({eyebrow:"MAKE IT YOURS",title:t("مساحتك. بطابع ناديك.","Your space. Your club's character."),description:t("اضبط الهوية والفروع والتجربة من مكان واحد.","Identity, branches and demo data in one place.")})}<section className="card theme-gallery"><h2>{t("اختار هوية التطبيق — ١٤ ثيم","App appearance — 14 themes")}</h2><p>{t("اختيار مشترك للموقع وWindows، محفوظ في بيانات النادي. التغيير للأدمن وصاحب النادي.","Shared by Windows and the website, saved with your gym. Only administrators and the owner can change it.")}</p><div className="theme-grid">{themes.map(theme=><button type="button" key={theme.id} aria-pressed={selectedTheme.id===theme.id} disabled={!canEdit||(busy||!admin)} onClick={()=>void mutate({type:"settings.save",name:s!.settings.name,currency:s!.settings.currency,theme:theme.id})} style={{background:theme.bg,color:theme.text,borderColor:selectedTheme.id===theme.id?theme.accent:undefined}}><span className="theme-swatch" style={{background:theme.surface}}><i style={{background:theme.accent}}/><i style={{background:theme.text}}/></span><b>{ar?theme.ar:theme.en}</b>{selectedTheme.id===theme.id&&<Check size={16}/>}</button>)}</div></section><div className="settings-grid"><section className="card"><div className="card-head"><div><h2>{t("هوية النادي","Club identity")}</h2><p>{t("اللوجو محفوظ مع بيانات حسابك.","Your logo stays with your account's data.")}</p></div><Building2 size={20}/></div><LogoPicker value={s!.settings.logo} ar={ar} busy={busy||!admin} onSave={logo=>mutate({type:"logo.set",logo})}/><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await mutate({type:"settings.save",name:f.get("name"),currency:f.get("currency")});}}><label>{t("اسم النادي","Club name")}<input name="name" required maxLength={150} defaultValue={s!.settings.name}/></label><label>{t("العملة","Currency")}<select name="currency" defaultValue={s!.settings.currency}>{["EGP","USD","EUR","GBP","AED","SAR"].map(c=><option key={c}>{c}</option>)}</select></label><button className="button primary" disabled={!canEdit||(busy)}><Check size={16}/>{t("حفظ التغييرات","Save changes")}</button></form></section><section className="card"><div className="card-head"><div><h2>{t("فروع النادي","Club branches")}</h2><p>{t("اعرض بيانات كل فرع على حدة.","View each branch's records separately.")}</p></div><Building2 size={20}/></div><div className="branch-list">{s!.branches.map(b=><button key={b.id} onClick={()=>onBranch(b.id)}><span className="stat-icon purple"><Building2 size={18}/></span><span>{b.name}</span>{branch===b.id&&<CheckCircle2 size={17}/>}</button>)}</div><button className="button secondary" onClick={()=>onModal({type:"branch"})} disabled={!canEdit}><Plus size={16}/>{t("إضافة فرع","Add branch")}</button><div className="account-note"><ShieldCheck size={21}/><div><b>{t("مساحة خاصة بحسابك","A private account workspace")}</b><p>{t("أضف المستخدمين وحدد أدوارهم وفروعهم من قسم المستخدمين والصلاحيات.","Add users and manage their roles and branches in Users & permissions.")}</p></div></div></section><section className="card"><div className="card-head"><div><h2>{t("بيانات التجربة","A space to try things out")}</h2><p>{t("سجلات وهمية واضحة العلامة، قابلة للمسح.","Clearly marked synthetic records you can remove.")}</p></div><Sparkles size={21}/></div><div className="demo-illustration"><Dumbbell size={35}/><span>{t("جرّب بثقة.","Explore with confidence.")}</span></div><p className="muted small">{t("الأرقام المعروضة تشمل التجربة أثناء وجودها. المسح يخص البيانات التجريبية في الفرع المفتوح ويترك بياناتك الحقيقية. سجل النشاط يحتفظ بأحداث التنفيذ.","Figures include samples while present. Clearing removes only the selected branch's demo records and keeps real data. Activity events remain in the history.")}</p>{demo?<button className="button danger-button" onClick={()=>onModal({type:"demo"})} disabled={!canEdit}><Trash2 size={16}/>{t("مسح البيانات التجريبية","Clear demo data")}</button>:<button className="button secondary" disabled={!canEdit||(busy)} onClick={()=>void mutate({type:"demo.seed"})}><Plus size={16}/>{t("إضافة بيانات تجريبية","Add sample data")}</button>}</section><section className="card"><div className="card-head"><div><h2>{t("التفضيلات والتصدير","Preferences & export")}</h2><p>{t("تفاصيل صغيرة، تجربة أفضل.","Small details. A better experience.")}</p></div><Settings size={20}/></div><div className="preference-row"><span>{t("لغة الواجهة","Interface language")}</span><button className="button secondary" onClick={onLanguage}>{ar?"English":"العربية"}</button></div><div className="preference-row"><span>{t("بيانات الأعضاء","Members data")}</span><button className="button secondary" onClick={()=>onExport("members")}><Download size={16}/>CSV</button></div><div className="preference-row"><span>{t("سجل التحصيل","Collection ledger")}</span><button className="button secondary" onClick={()=>onExport("payments")}><Download size={16}/>CSV</button></div><p className="small muted">{t("ملفات CSV غير مشفرة وقد تحتوي بيانات أعضاء. الوقت التشغيلي: القاهرة.","CSV files are unencrypted and may include member data. Operating timezone: Cairo.")}</p></section></div></fieldset>;}

 function SectionHead({eyebrow,title,description,actions}:{eyebrow?:string;title:string;description?:string;actions?:ReactNode}){return <div className="section-head"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1>{description&&<p>{description}</p>}</div><div className="head-actions">{actions}</div></div>;}
